export const capabilitiesToml = "# Every capability a plugin may ask for (Epic 54, story 54.01 §3; README §4.5).\n#\n# Read by the four manifest validators (Go shared/go/pluginmanifest, Rust\n# plugind/crates/pluginmanifest, Python maktaba_pipeline.plugins.manifest, TypeScript\n# tools/plugin-sdk/js/manifest.ts), by the host's import audit (54.02 §6) and by the\n# plugin API (54.04). The words an admin reads are Maktaba's own, keyed by title_key and\n# detail_key in web/src/i18n/{en,ar}.json, never the plugin's.\n#\n# Fields:\n#   name        the capability; a name with `param` takes \":<value>\" (plugin-data.read:<id>)\n#   risk        low | medium | high (the rating, story 54.08 §2)\n#   interface   the maktaba:plugin interface it unlocks (shared/plugins/wit)\n#   functions   the functions of that interface it unlocks (\"*\" every one)\n#   param       \"plugin_id\" when the name takes a plugin id\n#   since       the plugin API minor (1.x) that added it\n#\n# compute.embed and compute.llm (story 54.21) came with plugin API 1.1: a required one is\n# a `requires` of the plugin's component (search.semantic, llm), an optional one a `wants`.\n\nschema = 1\n\n[[capability]]\nname      = \"library.read\"\nrisk      = \"low\"\ninterface = \"library\"\nfunctions = [\"*\"]\ntitle_key = \"plugins.capability.library_read.title\"\ndetail_key = \"plugins.capability.library_read.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"transcript.read\"\nrisk      = \"medium\"\ninterface = \"transcript\"\nfunctions = [\"*\"]\ntitle_key = \"plugins.capability.transcript_read.title\"\ndetail_key = \"plugins.capability.transcript_read.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"media.read\"\nrisk      = \"medium\"\ninterface = \"media\"\nfunctions = [\"open\", \"read\", \"size\", \"close\"]\ntitle_key = \"plugins.capability.media_read.title\"\ndetail_key = \"plugins.capability.media_read.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"media.frames\"\nrisk      = \"medium\"\ninterface = \"media\"\nfunctions = [\"frame\"]\ntitle_key = \"plugins.capability.media_frames.title\"\ndetail_key = \"plugins.capability.media_frames.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"media.audio\"\nrisk      = \"medium\"\ninterface = \"media\"\nfunctions = [\"audio\"]\ntitle_key = \"plugins.capability.media_audio.title\"\ndetail_key = \"plugins.capability.media_audio.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"metadata.write\"\nrisk      = \"medium\"\ninterface = \"write\"\nfunctions = [\"set-field\"]\ntitle_key = \"plugins.capability.metadata_write.title\"\ndetail_key = \"plugins.capability.metadata_write.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"tags.write\"\nrisk      = \"low\"\ninterface = \"write\"\nfunctions = [\"add-tags\"]\ntitle_key = \"plugins.capability.tags_write.title\"\ndetail_key = \"plugins.capability.tags_write.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"chapters.write\"\nrisk      = \"low\"\ninterface = \"write\"\nfunctions = [\"set-chapters\"]\ntitle_key = \"plugins.capability.chapters_write.title\"\ndetail_key = \"plugins.capability.chapters_write.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"subtitles.write\"\nrisk      = \"low\"\ninterface = \"write\"\nfunctions = [\"add-subtitle\"]\ntitle_key = \"plugins.capability.subtitles_write.title\"\ndetail_key = \"plugins.capability.subtitles_write.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"artwork.write\"\nrisk      = \"low\"\ninterface = \"write\"\nfunctions = [\"set-artwork\"]\ntitle_key = \"plugins.capability.artwork_write.title\"\ndetail_key = \"plugins.capability.artwork_write.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"suggest\"\nrisk      = \"low\"\ninterface = \"suggest\"\nfunctions = [\"*\"]\ntitle_key = \"plugins.capability.suggest.title\"\ndetail_key = \"plugins.capability.suggest.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"jobs.enqueue\"\nrisk      = \"low\"\ninterface = \"queue\"\nfunctions = [\"*\"]\ntitle_key = \"plugins.capability.jobs_enqueue.title\"\ndetail_key = \"plugins.capability.jobs_enqueue.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"notify.admin\"\nrisk      = \"low\"\ninterface = \"notify\"\nfunctions = [\"*\"]\ntitle_key = \"plugins.capability.notify_admin.title\"\ndetail_key = \"plugins.capability.notify_admin.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"plugin-data.read\"\nrisk      = \"medium\"\ninterface = \"exports\"\nfunctions = [\"*\"]\nparam     = \"plugin_id\"\ntitle_key = \"plugins.capability.plugin_data_read.title\"\ndetail_key = \"plugins.capability.plugin_data_read.detail\"\nsince     = \"1.0\"\n\n[[capability]]\nname      = \"compute.embed\"\nrisk      = \"medium\"\ninterface = \"compute\"\nfunctions = [\"embed\"]\ntitle_key = \"plugins.capability.compute_embed.title\"\ndetail_key = \"plugins.capability.compute_embed.detail\"\nsince     = \"1.1\"\n\n[[capability]]\nname      = \"compute.llm\"\nrisk      = \"medium\"\ninterface = \"compute\"\nfunctions = [\"generate\"]\ntitle_key = \"plugins.capability.compute_llm.title\"\ndetail_key = \"plugins.capability.compute_llm.detail\"\nsince     = \"1.1\"\n\n# 54.40: subscribing to another plugin's published events. It unlocks no import (the\n# subscriber is only started); the admin's grant is what wires the subscription.\n[[capability]]\nname      = \"events.subscribe\"\nrisk      = \"medium\"\ninterface = \"events\"\nfunctions = []\nparam     = \"plugin_id\"\ntitle_key = \"plugins.capability.events_subscribe.title\"\ndetail_key = \"plugins.capability.events_subscribe.detail\"\nsince     = \"1.2\"\n";

export const eventsToml = "# The stable events a plugin stage can follow (Epic 54, README §4.2, story 54.06 §6).\n#\n# A plugin never names a core stage: it names an event, and this file maps the event to\n# the core stage whose output means it. When a core stage is renamed or split, only this\n# file changes. tools/ci/tests/test_plugin_events.py fails when an event names a stage\n# that is not in the pipeline's GRAPH, and when an event is removed without a new plugin\n# API major.\n#\n# Fields:\n#   name      the event a manifest's [[stage.trigger]] names\n#   subject   the subject kind of the jobs it starts (a trigger's stage must match it)\n#   stage     the core stage whose changed output fires it (\"\" for schedule)\n#   map       the Edge map from that stage's subject to this subject (engine/graph.py)\n#   trigger   false: not a [[stage.trigger]] event ([[schedule]] only)\n#   since     the plugin API minor (1.x) that added it\n#\n# series.changed starts a season job: the engine forms series as seasons (detect), and\n# seasons_changed is the map that names the seasons a detect pass changed.\n\nschema = 1\n\n[[event]]\nname    = \"video.added\"\nsubject = \"video\"\nstage   = \"probe\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"video.changed\"\nsubject = \"video\"\nstage   = \"content_hash\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"audio.ready\"\nsubject = \"video\"\nstage   = \"extract\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"transcript.ready\"\nsubject = \"video\"\nstage   = \"transcribe\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"subtitles.ready\"\nsubject = \"video\"\nstage   = \"subtitle_gen\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"thumbnails.ready\"\nsubject = \"video\"\nstage   = \"thumbnail\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"metadata.changed\"\nsubject = \"video\"\nstage   = \"enrich\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"series.changed\"\nsubject = \"season\"\nstage   = \"detect\"\nmap     = \"seasons_changed\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"library.scanned\"\nsubject = \"library\"\nstage   = \"scan\"\nmap     = \"same\"\nsince   = \"1.0\"\n\n[[event]]\nname    = \"schedule\"\nsubject = \"catalog\"\nstage   = \"\"\nmap     = \"catalog\"\ntrigger = false\nsince   = \"1.0\"\n";

export const flowSchema = "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://maktaba.dev/plugins/flow.schema.json\",\n  \"title\": \"Maktaba plugin flow (flow.toml), schema 1\",\n  \"description\": \"Epic 54 story 54.39 §1. The declared graph of a set of plugins that work together, read with the same keyword subset as manifest.schema.json. The checks across fields and across plugins (membership, the manifest match, the leaf rule, existence, cycles, depth) are in the flow checkers, shared/plugins/pluginflow (Go) and tools/plugin-sdk/js/src/flow.ts (TypeScript), tested on shared/plugins/testdata/flows.\",\n  \"type\": \"object\",\n  \"x-code\": \"flow_invalid\",\n  \"x-unknown-code\": \"flow_unknown_key\",\n  \"additionalProperties\": false,\n  \"required\": [\"schema\", \"id\", \"version\", \"strings\", \"plugin\"],\n  \"properties\": {\n    \"schema\": { \"type\": \"integer\", \"minimum\": 1, \"maximum\": 1, \"x-code\": \"flow_invalid\" },\n    \"id\": {\n      \"type\": \"string\",\n      \"maxLength\": 100,\n      \"pattern\": \"^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?){2,5}$\",\n      \"x-code\": \"flow_invalid\"\n    },\n    \"version\": {\n      \"type\": \"string\",\n      \"maxLength\": 64,\n      \"pattern\": \"^(0|[1-9][0-9]*)\\\\.(0|[1-9][0-9]*)\\\\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\\\\.[0-9A-Za-z-]+)*)?$\",\n      \"x-code\": \"flow_invalid\"\n    },\n    \"strings\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"required\": [\"name\"],\n      \"x-code\": \"flow_invalid\",\n      \"properties\": {\n        \"name\": { \"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_.-]{1,100}$\", \"x-code\": \"flow_invalid\" }\n      }\n    },\n    \"plugin\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"maxItems\": 20,\n      \"x-code\": \"flow_limit\",\n      \"items\": {\n        \"type\": \"object\",\n        \"additionalProperties\": false,\n        \"required\": [\"id\", \"version\", \"stage\"],\n        \"x-code\": \"flow_invalid\",\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"maxLength\": 100,\n            \"pattern\": \"^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?){2,5}$\",\n            \"x-code\": \"flow_invalid\"\n          },\n          \"version\": {\n            \"type\": \"string\",\n            \"maxLength\": 100,\n            \"pattern\": \"^ *(>=|>|<=|<|=) *[0-9]+\\\\.[0-9]+\\\\.[0-9]+ *(, *(>=|>|<=|<|=) *[0-9]+\\\\.[0-9]+\\\\.[0-9]+ *)*$\",\n            \"x-code\": \"flow_invalid\"\n          },\n          \"stage\": {\n            \"type\": \"array\",\n            \"minItems\": 1,\n            \"maxItems\": 20,\n            \"x-code\": \"flow_limit\",\n            \"items\": {\n              \"type\": \"object\",\n              \"additionalProperties\": false,\n              \"required\": [\"name\", \"subject\"],\n              \"x-code\": \"flow_invalid\",\n              \"properties\": {\n                \"name\": { \"type\": \"string\", \"pattern\": \"^[a-z][a-z0-9_]{0,39}$\", \"x-code\": \"flow_invalid\" },\n                \"subject\": { \"type\": \"string\", \"enum\": [\"video\", \"series\", \"season\", \"library\", \"catalog\"], \"x-code\": \"flow_invalid\" },\n                \"triggers\": {\n                  \"type\": \"array\",\n                  \"maxItems\": 10,\n                  \"uniqueItems\": true,\n                  \"default\": [],\n                  \"items\": {\n                    \"type\": \"string\",\n                    \"maxLength\": 200,\n                    \"pattern\": \"^((plugin:[a-z0-9]([a-z0-9-]*[a-z0-9])?(\\\\.[a-z0-9]([a-z0-9-]*[a-z0-9])?){2,5}/)?[a-z][a-z0-9_.]{0,63}|stage:[a-z][a-z0-9_]{0,39})$\"\n                  },\n                  \"x-code\": \"flow_invalid\"\n                },\n                \"emits\": {\n                  \"type\": \"array\",\n                  \"maxItems\": 20,\n                  \"uniqueItems\": true,\n                  \"default\": [],\n                  \"items\": { \"type\": \"string\", \"maxLength\": 64, \"pattern\": \"^[a-z][a-z0-9_]*(\\\\.[a-z][a-z0-9_]*)+$\" },\n                  \"x-code\": \"flow_invalid\"\n                },\n                \"may_request\": {\n                  \"type\": \"array\",\n                  \"maxItems\": 20,\n                  \"uniqueItems\": true,\n                  \"default\": [],\n                  \"items\": { \"type\": \"string\", \"pattern\": \"^[a-z][a-z0-9_]{0,39}$\" },\n                  \"x-code\": \"flow_invalid\"\n                }\n              }\n            }\n          },\n          \"event\": {\n            \"type\": \"array\",\n            \"maxItems\": 20,\n            \"default\": [],\n            \"x-code\": \"flow_limit\",\n            \"items\": {\n              \"type\": \"object\",\n              \"additionalProperties\": false,\n              \"required\": [\"name\", \"subject\", \"payload\"],\n              \"x-code\": \"flow_invalid\",\n              \"properties\": {\n                \"name\": { \"type\": \"string\", \"maxLength\": 64, \"pattern\": \"^[a-z][a-z0-9_]*(\\\\.[a-z][a-z0-9_]*)+$\", \"x-code\": \"flow_invalid\" },\n                \"subject\": { \"type\": \"string\", \"enum\": [\"video\", \"series\", \"season\", \"library\", \"catalog\"], \"x-code\": \"flow_invalid\" },\n                \"payload\": { \"type\": \"string\", \"pattern\": \"^events/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,99}\\\\.json$\", \"x-code\": \"flow_invalid\" }\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n}\n";

export const flowMessages = "{\n  \"flow_invalid\": {\n    \"en\": \"The flow ({detail}) is not valid.\",\n    \"ar\": \"التدفّق (⁦{detail}⁩) غير صالح.\"\n  },\n  \"flow_unknown_key\": {\n    \"en\": \"The flow has a field Maktaba does not know: {detail}.\",\n    \"ar\": \"في التدفّق حقل لا تعرفه مكتبة: ⁦{detail}⁩.\"\n  },\n  \"flow_limit\": {\n    \"en\": \"The flow is over a limit: {detail}.\",\n    \"ar\": \"التدفّق يتجاوز حدًّا: ⁦{detail}⁩.\"\n  },\n  \"flow_duplicate\": {\n    \"en\": \"The flow names {detail} twice.\",\n    \"ar\": \"يسمّي التدفّق ⁦{detail}⁩ مرّتين.\"\n  },\n  \"flow_not_member\": {\n    \"en\": \"The plugin {plugin} is not a member of its own flow at this version.\",\n    \"ar\": \"الإضافة ⁦{plugin}⁩ ليست عضوًا في تدفّقها بهذا الإصدار.\"\n  },\n  \"flow_manifest_mismatch\": {\n    \"en\": \"The manifest of {plugin} does not match its flow: {detail} differs.\",\n    \"ar\": \"بيان الإضافة ⁦{plugin}⁩ لا يطابق تدفّقها: ⁦{detail}⁩ مختلف.\"\n  },\n  \"flow_core_edge\": {\n    \"en\": \"{plugin} reaches a core stage ({detail}); plugin stages run only after core stages.\",\n    \"ar\": \"تصل الإضافة ⁦{plugin}⁩ إلى مرحلة أساسية (⁦{detail}⁩)؛ ولا تعمل مراحل الإضافات إلا بعد المراحل الأساسية.\"\n  },\n  \"flow_foreign_stage\": {\n    \"en\": \"{plugin} names a stage that is not its own ({detail}); plugins start each other only through published events.\",\n    \"ar\": \"تسمّي الإضافة ⁦{plugin}⁩ مرحلة ليست من مراحلها (⁦{detail}⁩)؛ ولا تشغّل الإضافات بعضها إلا عبر الأحداث المنشورة.\"\n  },\n  \"flow_foreign_event\": {\n    \"en\": \"{plugin} emits an event it does not publish ({detail}).\",\n    \"ar\": \"تُطلق الإضافة ⁦{plugin}⁩ حدثًا لا تنشره (⁦{detail}⁩).\"\n  },\n  \"flow_unknown_event\": {\n    \"en\": \"{plugin} follows an event no one publishes: {detail}.\",\n    \"ar\": \"تتبع الإضافة ⁦{plugin}⁩ حدثًا لا ينشره أحد: ⁦{detail}⁩.\"\n  },\n  \"flow_subject_mismatch\": {\n    \"en\": \"{plugin} follows an event about something else than its stage works on: {detail}.\",\n    \"ar\": \"تتبع الإضافة ⁦{plugin}⁩ حدثًا عن شيء غير الذي تعمل عليه مرحلتها: ⁦{detail}⁩.\"\n  },\n  \"flow_missing_plugin\": {\n    \"en\": \"{plugin} works with {detail}, which is not here at a version it accepts.\",\n    \"ar\": \"تعمل الإضافة ⁦{plugin}⁩ مع ⁦{detail}⁩، وهي غير موجودة هنا بإصدار تقبله.\"\n  },\n  \"flow_cycle\": {\n    \"en\": \"These plugins would start each other in a loop: {path}.\",\n    \"ar\": \"ستشغّل هذه الإضافات بعضها بعضًا في حلقة: ⁦{path}⁩.\"\n  },\n  \"flow_too_deep\": {\n    \"en\": \"This chain of plugin stages is longer than 16 steps: {path}.\",\n    \"ar\": \"سلسلة مراحل الإضافات هذه أطول من 16 خطوة: ⁦{path}⁩.\"\n  }\n}\n";

